import{_ as t,a,o,ai as r}from"./chunks/framework.BbOtTPsL.js";const u=JSON.parse('{"title":"Recipe: Build a Storefront","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/recipes/build-a-storefront.md","filePath":"api/recipes/build-a-storefront.md","lastUpdated":1782473079000}'),s={name:"api/recipes/build-a-storefront.md"};function i(c,e,d,h,n,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="recipe-build-a-storefront" tabindex="-1">Recipe: Build a Storefront <a class="header-anchor" href="#recipe-build-a-storefront" aria-label="Permalink to &quot;Recipe: Build a Storefront&quot;">​</a></h1><p>A storefront on the Shop API, from browsing to a placed order. Every request carries the <code>X-STOREFRONT-KEY</code> header; customer-scoped steps also carry the customer&#39;s <code>Authorization: Bearer &lt;token&gt;</code>.</p><p>Open each linked page for the exact request body and response shape.</p><h2 id="_1-authenticate-the-storefront" tabindex="-1">1. Authenticate the storefront <a class="header-anchor" href="#_1-authenticate-the-storefront" aria-label="Permalink to &quot;1. Authenticate the storefront&quot;">​</a></h2><p>Every Shop API request sends your storefront key:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-STOREFRONT-KEY: &lt;key&gt;</span></span></code></pre></div><p>For customer-scoped actions (their cart, account, orders), first log the customer in and keep the returned token:</p><ul><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> — <code>POST /api/shop/customers/login</code> → <code>data.token</code>. Send it as <code>Authorization: Bearer &lt;token&gt;</code> on later calls.</li><li>New customers: <a href="/api/rest-api/shop/customers/customer-registration.html">Customer Registration</a>.</li></ul><h2 id="_2-browse-the-catalog" tabindex="-1">2. Browse the catalog <a class="header-anchor" href="#_2-browse-the-catalog" aria-label="Permalink to &quot;2. Browse the catalog&quot;">​</a></h2><ol><li><a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> — build the navigation.</li><li><strong>List / search products</strong> — paginated with <code>?page=</code>, <code>?per_page=</code>, <code>?query=</code>, <code>?sort=</code>, and category / price / attribute filters.</li><li><strong>Product detail</strong> — fetch a single product for its price, images, and type-specific data (variants, bundle options, downloadable links, grouped items).</li></ol><h2 id="_3-cart" tabindex="-1">3. Cart <a class="header-anchor" href="#_3-cart" aria-label="Permalink to &quot;3. Cart&quot;">​</a></h2><ol><li><a href="/api/rest-api/shop/cart/create-cart.html">Create / Get Cart</a> — start or load the cart.</li><li><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> — <code>POST /api/shop/cart/items</code>, body <code>{ productId, quantity, ... }</code>. <strong>The extra fields depend on the product type</strong> (configurable products need their selected options; grouped / bundle / downloadable need their selections) — open the page for the exact shape per type.</li><li><a href="/api/rest-api/shop/cart/update-cart-item.html">Update Cart Item</a> · <a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a>.</li><li><a href="/api/rest-api/shop/cart/apply-coupon.html">Apply Coupon</a> · <a href="/api/rest-api/shop/cart/remove-coupon.html">Remove Coupon</a>.</li></ol><h2 id="_4-checkout-in-order-—-the-sequence-is-enforced" tabindex="-1">4. Checkout (in order — the sequence is enforced) <a class="header-anchor" href="#_4-checkout-in-order-—-the-sequence-is-enforced" aria-label="Permalink to &quot;4. Checkout (in order — the sequence is enforced)&quot;">​</a></h2><ol><li><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a></li><li><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a></li><li><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">Get Shipping Methods</a> → <a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a></li><li><a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a> → <a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a></li><li><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a></li></ol><h2 id="_5-post-order" tabindex="-1">5. Post-order <a class="header-anchor" href="#_5-post-order" aria-label="Permalink to &quot;5. Post-order&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> and the single order for the confirmation screen.</li><li><a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get Customer Invoices</a> for downloadable invoices.</li></ul><h2 id="graphql-variant" tabindex="-1">GraphQL variant <a class="header-anchor" href="#graphql-variant" aria-label="Permalink to &quot;GraphQL variant&quot;">​</a></h2><p>Every step above has a GraphQL equivalent at <code>POST /api/graphql</code> (see the Shop GraphQL section). When mutating the cart or placing the order, <strong>select the result fields</strong> the mutation returns (cart contents, order id, <code>success</code>, <code>message</code>) — the cart/checkout mutations are actions, so don&#39;t select an <code>id</code> on them.</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p><code>200/201</code> success · <code>401</code> unauthenticated (missing key/token) · <code>403</code> forbidden · <code>400</code> bad input · <code>404</code> not found · <code>422</code> validation (e.g. quantity exceeds stock).</p>',20)]))}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
